/// Native replay implementations for random bindings.
#[inline]
fn destack_random_secure_metadata_replay(
    binding: &BindingCallContext,
    out: *mut SecureRandomMetadata,
) -> RuntimeResult<()> {
    binding.trace().run_binding_without_context(
        RANDOM_SECURE_METADATA,
        binding.replay_payload_for(RANDOM_SECURE_METADATA)?,
        || unsafe { platform_runtime_native::destack_random_secure_metadata(binding, out) },
        |result| {
            if let Ok(()) = result {
                let result_value: SecureRandomMetadata = unsafe { out.read() };
                let result_recorded_source = result_value.source;
                let result_recorded_backend_name =
                    unsafe { result_value.backend_name.as_str()? }.to_string();
                let result_recorded_may_block = result_value.may_block;
                let result_recorded_is_cryptographic = result_value.is_cryptographic;
                let result_recorded_is_seeded = result_value.is_seeded;
                let result_recorded_is_fips_approved = result_value.is_fips_approved;
                let result_recorded_entropy_bits_per_byte = result_value.entropy_bits_per_byte;
                let result_recorded = SecurerandommetadataReplayRecord {
                    source: result_recorded_source,
                    backend_name: result_recorded_backend_name,
                    may_block: result_recorded_may_block,
                    is_cryptographic: result_recorded_is_cryptographic,
                    is_seeded: result_recorded_is_seeded,
                    is_fips_approved: result_recorded_is_fips_approved,
                    entropy_bits_per_byte: result_recorded_entropy_bits_per_byte,
                };
                let payload = RandomSecureMetadataReplayRecord {
                    result: Ok(result_recorded),
                };
                return Ok(Some(payload));
            }

            if let Err(error) = result {
                let payload = {
                    let result = Err(TraceError::from(error.as_ref()));
                    RandomSecureMetadataReplayRecord { result }
                };
                return Ok(Some(payload));
            }

            Ok(None)
        },
        |payload| {
            // replay result
            match payload.result {
                Ok(value) => {
                    let value_native_source = value.source;
                    let value_native_backend_name = binding.store_string_owned(value.backend_name);
                    let value_native_may_block = value.may_block;
                    let value_native_is_cryptographic = value.is_cryptographic;
                    let value_native_is_seeded = value.is_seeded;
                    let value_native_is_fips_approved = value.is_fips_approved;
                    let value_native_entropy_bits_per_byte = value.entropy_bits_per_byte;
                    let value_native = SecureRandomMetadata {
                        source: value_native_source,
                        backend_name: value_native_backend_name,
                        may_block: value_native_may_block,
                        is_cryptographic: value_native_is_cryptographic,
                        is_seeded: value_native_is_seeded,
                        is_fips_approved: value_native_is_fips_approved,
                        entropy_bits_per_byte: value_native_entropy_bits_per_byte,
                    };
                    unsafe { out.write(value_native) };
                    Ok(())
                }
                Err(error) => Err(Box::<RuntimeError>::from(error)),
            }
        },
    )
}

#[inline]
fn destack_random_stream_export_replay(
    binding: &BindingCallContext,
    out: *mut RandomStreamState,
    stream: RandomStream,
) -> RuntimeResult<()> {
    let _ = &stream;

    binding.trace().run_binding_without_context(
        RANDOM_STREAM_EXPORT,
        binding.replay_payload_for(RANDOM_STREAM_EXPORT)?,
        || unsafe { platform_runtime_native::destack_random_stream_export(binding, out, stream) },
        |result| {
            if let Ok(()) = result {
                let result_value: RandomStreamState = unsafe { out.read() };
                let result_recorded_version = result_value.version;
                let result_recorded_bytes_slice = unsafe { result_value.bytes.as_slice()? };
                let mut result_recorded_bytes =
                    Vec::with_capacity(result_recorded_bytes_slice.len());
                for result_recorded_bytes_item in result_recorded_bytes_slice.iter().cloned() {
                    let result_recorded_bytes_item_recorded = result_recorded_bytes_item;
                    result_recorded_bytes.push(result_recorded_bytes_item_recorded);
                }
                let result_recorded = RandomstreamstateReplayRecord {
                    version: result_recorded_version,
                    bytes: result_recorded_bytes,
                };
                let payload = RandomStreamExportReplayRecord {
                    result: Ok(result_recorded),
                };
                return Ok(Some(payload));
            }

            if let Err(error) = result {
                let payload = {
                    let result = Err(TraceError::from(error.as_ref()));
                    RandomStreamExportReplayRecord { result }
                };
                return Ok(Some(payload));
            }

            Ok(None)
        },
        |payload| {
            // replay result
            match payload.result {
                Ok(value) => {
                    let value_native_version = value.version;
                    let value_native_bytes = binding.store_array_with(
                        value.bytes.len(),
                        |value_native_bytes_values| {
                            for value_native_bytes_item in value.bytes {
                                let value_native_bytes_decoded = value_native_bytes_item;
                                value_native_bytes_values.push(value_native_bytes_decoded);
                            }
                            Ok(())
                        },
                    )?;
                    let value_native = RandomStreamState {
                        version: value_native_version,
                        bytes: value_native_bytes,
                    };
                    unsafe { out.write(value_native) };
                    Ok(())
                }
                Err(error) => Err(Box::<RuntimeError>::from(error)),
            }
        },
    )
}

