/// Native export wrappers for random bindings.
#[unsafe(export_name = "destack.random.secure.bytes")]
pub(crate) unsafe extern "C" fn destack_random_secure_bytes(
    buffer: NativeSlice<u8>,
) -> RuntimeStatus {
    native_call(|context| {
        let _ = &buffer;

        context.trace().run_random_bytes(
            context.entropy_subject(RANDOM_SECURE_BYTES),
            context.random_stream_id(),
            buffer.len,
            || context.on_random_read(),
            || {
                let _binding_hook_guard = context.on_before_binding(RANDOM_SECURE_BYTES)?;
                unsafe { platform_runtime_native::destack_random_secure_bytes(context, buffer) }
            },
            || {
                let slice = unsafe { buffer.as_slice()? };
                Ok(slice.to_vec())
            },
            |bytes| {
                let slice = unsafe { buffer.as_mut_slice()? };
                if slice.len() != bytes.len() {
                    return Err(RuntimeError::from(PlatformError::invalid_argument_value(
                        "buffer",
                        "buffer length mismatch",
                    ))
                    .boxed());
                }
                slice.copy_from_slice(&bytes);
                Ok(())
            },
        )
    })
}

