#[inline]
fn destack_random_stream_split_vm_replay(
    binding: &BindingCallContext,
    context: &mut vm::BindingContext<'_>,
    parent: RandomStream,
) -> RuntimeResult<vm::Word> {
    let result = binding.trace().run_binding(
        RANDOM_STREAM_SPLIT,
        binding.replay_payload_for(RANDOM_STREAM_SPLIT)?,
        context,
        |context| platform_runtime_vm::destack_random_stream_split(binding, context, parent),
        |_context, result| {
            if let Ok(value) = result {
                let result_value: RandomStream = value.clone();
                let result_recorded = result_value;
                let payload = RandomStreamSplitReplayRecord {
                    result: Ok(result_recorded),
                };
                return Ok(Some(payload));
            }

            if let Err(error) = result {
                let payload = {
                    let result = Err(TraceError::from(error.as_ref()));
                    RandomStreamSplitReplayRecord { result }
                };
                return Ok(Some(payload));
            }

            Ok(None)
        },
        |_context, payload| {
            // replay result
            match payload.result {
                Ok(value) => {
                    let vm_result = value;
                    Ok(vm_result)
                }
                Err(error) => Err(Box::<RuntimeError>::from(error)),
            }
        },
    );
    let result = encode_destack_random_stream_split_result(context, result)?;
    Ok(result)
}

/// Register VM bindings for random.
pub(crate) fn register_random_vm_bindings(registry: &mut BindingRegistry, isolate: &mut Isolate) {
    {
        binding!(
            registry,
            isolate,
            RANDOM_SECURE_BYTES,
            move |context, args| {
                with_binding_call_context(|binding| {
                    // decode args
                    let (buffer,) = decode_destack_random_secure_bytes_args(context, args)?;

                    // execute binding
                    let context_ptr = context as *mut vm::BindingContext<'_>;
                    let result = binding.trace().run_random_bytes(
                        binding.entropy_subject(RANDOM_SECURE_BYTES),
                        binding.random_stream_id(),
                        buffer.len,
                        || binding.on_random_read(),
                        || unsafe {
                            {
                                let _binding_hook_guard =
                                    binding.on_before_binding(RANDOM_SECURE_BYTES)?;
                                platform_runtime_vm::destack_random_secure_bytes(
                                    binding,
                                    &mut *context_ptr,
                                    buffer,
                                )
                            }
                        },
                        || unsafe {
                            let context = (&*context_ptr).read();
                            buffer.read_bytes(&context)
                        },
                        |bytes| unsafe {
                            let mut context = (&mut *context_ptr).write();
                            buffer.write_bytes(&mut context, &bytes)
                        },
                    );
                    encode_destack_random_secure_bytes_result(context, result)
                })
                .map_err(Into::into)
            }
        );
    }
    {
        binding!(
            registry,
            isolate,
            RANDOM_SECURE_BYTES_TRY,
            move |context, args| {
                with_binding_call_context(|binding| {
                    // decode args
                    let (buffer,) = decode_destack_random_secure_bytes_try_args(context, args)?;

                    // execute binding
                    let context_ptr = context as *mut vm::BindingContext<'_>;
                    let result = binding.trace().run_random_bytes(
                        binding.entropy_subject(RANDOM_SECURE_BYTES_TRY),
                        binding.random_stream_id(),
                        buffer.len,
                        || binding.on_random_read(),
                        || unsafe {
                            {
                                let _binding_hook_guard =
                                    binding.on_before_binding(RANDOM_SECURE_BYTES_TRY)?;
                                platform_runtime_vm::destack_random_secure_bytes_try(
                                    binding,
                                    &mut *context_ptr,
                                    buffer,
                                )
                            }
                        },
                        || unsafe {
                            let context = (&*context_ptr).read();
                            buffer.read_bytes(&context)
                        },
                        |bytes| unsafe {
                            let mut context = (&mut *context_ptr).write();
                            buffer.write_bytes(&mut context, &bytes)
                        },
                    );
                    encode_destack_random_secure_bytes_try_result(context, result)
                })
                .map_err(Into::into)
            }
        );
    }
    {
        binding!(
            registry,
            isolate,
            RANDOM_SECURE_METADATA,
            move |context, _args| {
                with_binding_call_context(|binding| {
                    // execute binding
                    let _binding_hook_guard = binding.on_before_binding(RANDOM_SECURE_METADATA)?;
                    destack_random_secure_metadata_vm_replay(binding, context)
                })
                .map_err(Into::into)
            }
        );
    }
    {
        binding!(
            registry,
            isolate,
            RANDOM_STREAM_CREATE,
            move |context, _args| {
                with_binding_call_context(|binding| {
                    // execute binding
                    let result = binding.trace().run_random_stream(
                        binding.entropy_subject(RANDOM_STREAM_CREATE),
                        || binding.on_random_read(),
                        || {
                            {
                                let _binding_hook_guard =
                                    binding.on_before_binding(RANDOM_STREAM_CREATE)?;
                                platform_runtime_vm::destack_random_stream(binding, context)
                            }
                            .map(|stream| stream.0)
                        },
                    );
                    let result = result.map(RandomStream);
                    encode_destack_random_stream_create_result(context, result)
                })
                .map_err(Into::into)
            }
        );
    }
    {
        binding!(
            registry,
            isolate,
            RANDOM_STREAM_EXPORT,
            move |context, args| {
                with_binding_call_context(|binding| {
                    // decode args
                    let (stream,) = decode_destack_random_stream_export_args(context, args)?;

                    // execute binding
                    let _binding_hook_guard = binding.on_before_binding(RANDOM_STREAM_EXPORT)?;
                    destack_random_stream_export_vm_replay(binding, context, stream)
                })
                .map_err(Into::into)
            }
        );
    }
    {
        binding!(
            registry,
            isolate,
            RANDOM_STREAM_FILL_BYTES,
            move |context, args| {
                with_binding_call_context(|binding| {
                    // decode args
                    let (buffer,) = decode_destack_random_stream_fill_bytes_args(context, args)?;

                    // execute binding
                    let context_ptr = context as *mut vm::BindingContext<'_>;
                    let result = binding.trace().run_random_bytes(
                        binding.entropy_subject(RANDOM_STREAM_FILL_BYTES),
                        binding.random_stream_id(),
                        buffer.len,
                        || binding.on_random_read(),
                        || unsafe {
                            {
                                let _binding_hook_guard =
                                    binding.on_before_binding(RANDOM_STREAM_FILL_BYTES)?;
                                platform_runtime_vm::destack_random_fill_bytes(
                                    binding,
                                    &mut *context_ptr,
                                    buffer,
                                )
                            }
                        },
                        || unsafe {
                            let context = (&*context_ptr).read();
                            buffer.read_bytes(&context)
                        },
                        |bytes| unsafe {
                            let mut context = (&mut *context_ptr).write();
                            buffer.write_bytes(&mut context, &bytes)
                        },
                    );
                    encode_destack_random_stream_fill_bytes_result(context, result)
                })
                .map_err(Into::into)
            }
        );
    }
    {
        binding!(
            registry,
            isolate,
            RANDOM_STREAM_FILL_BYTES_FROM,
            move |context, args| {
                with_binding_call_context(|binding| {
                    // decode args
                    let (stream, buffer) =
                        decode_destack_random_stream_fill_bytes_from_args(context, args)?;

                    // execute binding
                    let context_ptr = context as *mut vm::BindingContext<'_>;
                    let result = binding.trace().run_random_bytes(
                        binding.entropy_subject(RANDOM_STREAM_FILL_BYTES_FROM),
                        RandomStreamId::new(stream.0),
                        buffer.len,
                        || binding.on_random_read(),
                        || unsafe {
                            {
                                let _binding_hook_guard =
                                    binding.on_before_binding(RANDOM_STREAM_FILL_BYTES_FROM)?;
                                platform_runtime_vm::destack_random_fill_bytes_from(
                                    binding,
                                    &mut *context_ptr,
                                    stream,
                                    buffer,
                                )
                            }
                        },
                        || unsafe {
                            let context = (&*context_ptr).read();
                            buffer.read_bytes(&context)
                        },
                        |bytes| unsafe {
                            let mut context = (&mut *context_ptr).write();
                            buffer.write_bytes(&mut context, &bytes)
                        },
                    );
                    encode_destack_random_stream_fill_bytes_from_result(context, result)
                })
                .map_err(Into::into)
            }
        );
    }
    {
        binding!(
            registry,
            isolate,
            RANDOM_STREAM_IMPORT,
            move |context, args| {
                with_binding_call_context(|binding| {
                    // decode args
                    let (stream, state) = decode_destack_random_stream_import_args(context, args)?;

                    // execute binding
                    let _binding_hook_guard = binding.on_before_binding(RANDOM_STREAM_IMPORT)?;
                    destack_random_stream_import_vm_replay(binding, context, stream, state)
                })
                .map_err(Into::into)
            }
        );
    }
    {
        binding!(registry, isolate, RANDOM_STREAM_IN, move |context, args| {
            with_binding_call_context(|binding| {
                // decode args
                let (domain,) = decode_destack_random_stream_in_args(context, args)?;

                // execute binding
                let result = binding.trace().run_random_stream(
                    binding.entropy_subject(RANDOM_STREAM_IN),
                    || binding.on_random_read(),
                    || {
                        {
                            let _binding_hook_guard =
                                binding.on_before_binding(RANDOM_STREAM_IN)?;
                            platform_runtime_vm::destack_random_stream_in(binding, context, domain)
                        }
                        .map(|stream| stream.0)
                    },
                );
                let result = result.map(RandomStream);
                encode_destack_random_stream_in_result(context, result)
            })
            .map_err(Into::into)
        });
    }
    {
        binding!(
            registry,
            isolate,
            RANDOM_STREAM_JUMP,
            move |context, args| {
                with_binding_call_context(|binding| {
                    // decode args
                    let (stream, jump) = decode_destack_random_stream_jump_args(context, args)?;

                    // execute binding
                    let _binding_hook_guard = binding.on_before_binding(RANDOM_STREAM_JUMP)?;
                    destack_random_stream_jump_vm_replay(binding, context, stream, jump)
                })
                .map_err(Into::into)
            }
        );
    }
    {
        binding!(
            registry,
            isolate,
            RANDOM_STREAM_NEXT_U64,
            move |context, _args| {
                with_binding_call_context(|binding| {
                    // execute binding
                    let result = binding.trace().run_random_u64(
                        binding.entropy_subject(RANDOM_STREAM_NEXT_U64),
                        binding.random_stream_id(),
                        || binding.on_random_read(),
                        || {
                            let _binding_hook_guard =
                                binding.on_before_binding(RANDOM_STREAM_NEXT_U64)?;
                            platform_runtime_vm::destack_random_next_u64(binding, context)
                        },
                    );
                    encode_destack_random_stream_next_u64_result(context, result)
                })
                .map_err(Into::into)
            }
        );
    }
    {
        binding!(
            registry,
            isolate,
            RANDOM_STREAM_NEXT_U64_FROM,
            move |context, args| {
                with_binding_call_context(|binding| {
                    // decode args
                    let (stream,) = decode_destack_random_stream_next_u64_from_args(context, args)?;

                    // execute binding
                    let result = binding.trace().run_random_u64(
                        binding.entropy_subject(RANDOM_STREAM_NEXT_U64_FROM),
                        RandomStreamId::new(stream.0),
                        || binding.on_random_read(),
                        || {
                            let _binding_hook_guard =
                                binding.on_before_binding(RANDOM_STREAM_NEXT_U64_FROM)?;
                            platform_runtime_vm::destack_random_next_u64_from(
                                binding, context, stream,
                            )
                        },
                    );
                    encode_destack_random_stream_next_u64_from_result(context, result)
                })
                .map_err(Into::into)
            }
        );
    }
    {
        binding!(
            registry,
            isolate,
            RANDOM_STREAM_SPLIT,
            move |context, args| {
                with_binding_call_context(|binding| {
                    // decode args
                    let (parent,) = decode_destack_random_stream_split_args(context, args)?;

                    // execute binding
                    let _binding_hook_guard = binding.on_before_binding(RANDOM_STREAM_SPLIT)?;
                    destack_random_stream_split_vm_replay(binding, context, parent)
                })
                .map_err(Into::into)
            }
        );
    }
}

/// Install VM bindings for random.
pub(crate) fn install_random_vm_bindings(
    registry: &mut BindingRegistry,
    isolate: &mut Isolate,
) -> vm::Result<()> {
    super::abi_generated::register_random_vm_aggregate_types(isolate)?;
    register_random_vm_bindings(registry, isolate);

    Ok(())
}

vm_binding_set!(pub(crate) RANDOM_VM_BINDINGS, "random", install_random_vm_bindings);
